  GB = `The Steam Awards`,
  KB = `Nominee`,
  qB = `Steam Awards Nominee`,
  JB = `Nominate now. Vote this December.`,
  YB = `This event's Steam Awards has ended. Check back in during this year's Autumn and Winter sale for the annual Steam Awards!`,
  XB = `December %1$s`,
  ZB = `Click below to vote for %1$s:`,
  QB = `The developers of %1$s would like your nomination for the category below.`,
  $B = `Click here to nominate %1$s for a category on the Steam Awards page.`,
  eV = `Nominations have closed. Vote during the Winter Sale. Winners announced January 2nd.`,
  tV = `Voting has ended. Click here to see the results.`,
  nV = `Nominate for:`,
  rV = `View your nominations`,
  iV = `Nominate this game for %1$s`,
  aV = `You've nominated this game for %1$s`,
  oV = `Game of the Year`,
  sV = `VR Game of the Year`,
  cV = `Labor of Love`,
  lV = `Better With Friends`,
  uV = `Outstanding Visual Style`,
  dV = `Most Innovative Gameplay`,
  fV = `Best Game You Suck At`,
  pV = `Best Soundtrack`,
  mV = `Outstanding Story-Rich Game`,
  hV = `Sit Back and Relax`,
  gV = `Do not suggest a specific category, and instead let your fans pick the category they think best fits your game. The event will still include a link to the nominations page.`,
  _V = `No Category`,
  vV = `Maybe it was its immersive gameplay, or its gripping story... its well-crafted characters, immaculate design, or addictive multiplayer. Whatever the reason, the winner of 2020's Game of the Year Award is an instant classic.`,
  yV = `The VR Game of the Year isn't merely masquerading as regular reality. This game improves on reality, taking advantage of the medium of VR and pushing the boundaries of the virtual realm.`,
  bV = `This game has been out for a while. The team is well past the debut of their creative baby, but being the good parents they are, these devs continue to nurture and support their creation. This game, to this day, is still getting new content after all these years.`,
  xV = `There are some games out there that just aren't the same when you play by yourself. Maybe you need to have a friend to watch your back. Maybe you need to have a friend that you can stab in their back. Either way, fun is awaiting those who gather friends together play this game.`,
  SV = `Visual style doesn't aspire to real-world graphical fidelity (though a noble goal in itself)… it describes a distinctive look and feel that suffuses an entire game.`,
  CV = `The designers of this game are at the front lines of creative experimentation, bringing a fresh perspective and brain-breaking surprises. This game delighted, inspired and entertained with newness never played before.`,
  wV = `This is the game that rewards persistence, and is not for the faint of heart. It's the toughest game we've ever loved.`,
  TV = `This unsung hero deserves to be recognized for its outstanding musical score. It's the OST with the MOST! `,
  EV = `Some days, only a narrative-heavy game will hit the spot, and this one packs a wallop. It's as gripping as any soap opera, and as well-tuned as a prestige-TV screenplay. Bravissimo -- for making us feel things!`,
  DV = `This game is the antidote to a busy day. It's smooth, it's relaxing, it lets your worries melt away. This game is your moment of zen.`,
  OV = `Change your nomination?`,
  kV = `You can only nominate one game for each category, and you have already nominated %1$s for this one. Would you like to nominate %2$s instead?`,
