  PV = `You can only vote for one game for each category, and you have already voted for %1$s for this one. Would you like to change your vote to %2$s?`,
  FV = `It appears that your account is limited. To prevent nomination abuse, you must spend $5 USD on Steam in order to participate in the Steam Awards. %1$s for more information.`,
