  WV = `Best Soundtrack`,
  GV = `Outstanding Story-Rich Game`,
  KV = `Sit Back and Relax`,
  qV = `Maybe it was its immersive gameplay, or its gripping story... its well-crafted characters, immaculate design, or addictive multiplayer. Whatever the reason, the winner of this year's Game of the Year Award is an instant classic.`,
  JV = `The VR Game of the Year isn't merely masquerading as regular reality. This game improves on reality, taking advantage of the medium of VR and pushing the boundaries of the virtual realm.`,
  YV = `This game has been out for a while. The team is well past the debut of their creative baby, but being the good parents they are, these devs continue to nurture and support their creation. This game, to this day, is still getting new content after all these years.`,
  XV = `There are some games out there that just aren't the same when you play by yourself. Maybe you need to have a friend to watch your back. Maybe you need to have a friend that you can stab in their back. Either way, fun is awaiting those who gather friends together play this game.`,
  ZV = `Visual style doesn't aspire to real-world graphical fidelity (though a noble goal in itself)… it describes a distinctive look and feel that suffuses an entire game.`,
  QV = `The designers of this game are at the front lines of creative experimentation, bringing a fresh perspective and brain-breaking surprises. This game delighted, inspired and entertained with newness never played before.`,
  $V = `This is the game that rewards persistence, and is not for the faint of heart. It's the toughest game we've ever loved.`,
