  SH = `Some days, only a narrative-heavy game will hit the spot, and this one packs a wallop. It's as gripping as any soap opera, and as well-tuned as a prestige-TV screenplay. Bravissimo -- for making us feel things!`,
  CH = `This game is the antidote to a busy day. It's smooth, it's relaxing, it lets your worries melt away. This game is your moment of zen.`,
  wH = `This game was so good, you wanted to take it everywhere. So you did! And luckily, everything that made it endlessly playable at your desk got even better on the go.`,
